  /** Manage local port-forward tunnels to a configured SSH host. Start a tunnel to reach a remote internal service (database, web UI, API) through 127.0.0.1 on this machine. */
  ssh_tunnel: {
    /** start / list / stop / stop-all. */
    action: "start" | "list" | "stop" | "stop-all";
    /** Host alias (required for start, optional for stop-all). */
    alias?: string;
    /** Port on the remote side (required for start). */
    remotePort?: number;
    /** Remote host to forward to (default 127.0.0.1 — the server itself). */
    remoteHost?: string;
    /** Local listening port (default: auto-assigned). */
    localPort?: number;
    /** Tunnel id (required for stop). */
    tunnelId?: string;
  } & Record<string, JsonValue>;
  /** Transfer a file FROM this machine (the dsh host) TO a remote SSH host. Use this only when the file must be copied to the remote host. Files that stay on this machine are handled with the local file tools (read / write / edit), not ssh_upload. */
  ssh_upload: {
    /** Host alias from ssh_list. */
    alias: string;
    /** Absolute path of the source file on THIS machine (the dsh host) — not a path on the remote host. */
    localPath: string;
    /** Absolute destination path on the remote SSH host (parent dirs are created). */
    remotePath: string;
  } & Record<string, JsonValue>;
  /** Delegate a self-contained task to a subagent (a separate agent that works in its own context) to offload focused, independent work — research, a scoped implementation, an analysis — so it does not consume this conversation's context. The subagent returns its result, not its intermediate steps. It runs in the background by default and returns a subagent id you can continue with `send_message`; you are notified when the run settles. Child LLM selection is optional. Omit `provider`, `model`, and `reasoning_effort` to use configured child defaults and inherit compatible missing values from the parent Agent. Supply `provider` and `model` together after using `list_subagent_models` to inspect advertised routes and efforts. Changing the effective route without naming an effort uses the selected model's default effort. */
  subagent: {
    /** A short (3-5 word) description of the delegated task, for display. */
    description: string;
    /** The complete, self-contained task for the subagent. It does not share this conversation's context, so include everything it needs. */
    prompt: string;
    /** LLM provider route for the child. Supply together with model; omit both to use configured child defaults or inherit the parent route. */
    provider?: string;
    /** Model id interpreted by provider. Supply together with provider; omit both to use configured child defaults or inherit the parent route. */
    model?: string;
    /** Adapter-owned reasoning effort for the effective child route. Omit to inherit a compatible configured/parent effort or use a newly selected model's default. */
    reasoning_effort?: string;
    /** Defaults to true. Set false only when your next action depends on the result. */
    run_in_background?: boolean;
  } & Record<string, JsonValue>;
  /** Delegate a task to a subagent that inherits this conversation: a child agent seeded with all completed turns so far (it does not see the current in-flight turn). Use this when the subtask builds on this conversation's context — a follow-up analysis, a review, a continuation — without consuming this conversation's context for the work itself. You receive its result, not its intermediate steps. It runs in the background by default and returns a subagent id you can continue with `send_message`; you are notified when the run settles. */
  subagent_fork: {
    /** A short (3-5 word) description of the delegated task, for display. */
    description: string;
    /** The task for the subagent. It already sees this conversation's completed turns, so build on them freely and state only what is new. */
    prompt: string;
    /** Defaults to true. Set false only when your next action depends on the result. */
    run_in_background?: boolean;
  } & Record<string, JsonValue>;
  /** Create a task on the DSH task board, or a subtask by passing parentId. A subtask inherits every execution target it does not override (workspace, agent preset, permission, model) from its parent, and inherits the parent human permission confirmation together with an inherited binding. The deployment caps subtask depth (default one level, maximum three): a subtask of a subtask is refused unless the board is configured deeper. The task lands in the todo column and does NOT run; call task_board_run to execute it. */
  task_board_create: {
    /** Short display title (one line). */
    title: string;
    /** Longer human description shown in the detail view. */
    description?: string;
    /** The instruction sent to the execution agent; the title is used when blank. */
    prompt?: string;
    /** Parent task id, making this a subtask. Omit for a root task. */
    parentId?: string;
    /** Workspace id the execution must run in; omit to inherit the workspace this session is in (root task) or the parent value (subtask). */
    workspaceId?: string;
    /** Agent preset id the execution session is composed from; omit for the deployment default or the parent value. */
    mode?: string;
    /** Permission preset for the execution session. Omit to inherit the parent binding; a value above the session default needs a human confirmation in the board UI before the card can run. */
    permission?: "read-only" | "workspace-write" | "danger-full-access";
    /** Pinned model as provider/model (or a model id); omit for the host default or the parent value. */
    model?: string;
    /** Continue later runs in the previous execution session instead of a fresh conversation. */
    reuseSession?: boolean;
    /** Run this task as an Agent Team: running it starts one Team Lead session and the Host spawns a teammate per subtask inside it. Omit or false for one independent session per member. Refused when the deployment serves no Agent Teams service. */
    teamRun?: boolean;
    /** Start each run with dsh built-in /goal so the session keeps working continuation rounds until the goal completes. Default true (omit to keep it); pass false for a single plain turn. */
    goalRun?: boolean;
    /** Run this task without the board acceptance gate: update_goal may mark the goal complete without a passing acceptance, and the execution record is marked skipped. Default false (omit to inherit the board-wide acceptance switch). Only affects executions started afterwards. */
    skipVerification?: boolean;
    /** Labels: the name renders as a badge and drives the board filter; promptPrefix is injected ahead of the execution prompt on every run. */
    tags?: {
      /** Label name (unique within the task, at most 32 characters). */
      name: string;
      /** Optional prompt line injected before the task prompt (at most 200 characters). */
      promptPrefix?: string;
    }[];
    /** Arm a 5-field cron schedule at creation time (Host local time zone). */
    schedule?: {
      /** Whether the schedule is armed. */
      enabled: boolean;
      /** 5-field cron: minute hour day-of-month month day-of-week. */
      cron: string;
    };
  } & Record<string, JsonValue>;
  /** Read one task board card in full: prompt, description, labels, column, parent link, direct subtasks, execution targets, schedule, permission gate state, and the last ten execution attempts with their session ids and outcomes. Use it before running or editing a card, and after a run to read the settled outcome. */
  task_board_get: {
    /** Task id, as reported by task_board_list or task_board_create. */
    taskId: string;
  } & Record<string, JsonValue>;
  /** Close the GitHub issue behind a task board card, once the work has actually landed. Refused unless the card has a linked pull request that is MERGED: a passing local run is not a reviewed change. Does not run shell commands. */
  task_board_github_close_issue: {
    /** Task ID linked to a GitHub issue. */
    taskId: string;
  } & Record<string, JsonValue>;
  /** Post one comment on the GitHub issue behind a task board card. Use it to report what was done, link the pull request, or state why the task was closed without a fix. The body is Markdown and must stay under the length limit. Does not run shell commands. */
  task_board_github_comment: {
    /** Task ID linked to a GitHub issue. */
    taskId: string;
    /** Markdown comment body to post. Must be non-empty and under the length limit; a transcript belongs in the card, not in a comment. */
    body: string;
  } & Record<string, JsonValue>;
  /** Create a GitHub Pull Request for a task board card linked to a GitHub issue. Verifies that the head branch exists on remote, creates the PR, records PR metadata, and adds the PR phase label to the issue. Does not run shell commands. */
  task_board_github_create_pr: {
    /** Task ID linked to a GitHub issue. */
    taskId: string;
    /** Remote head branch containing the changes (must already exist on remote). */
    headBranch: string;
    /** Target base branch (default: repository default, e.g. main). */
    baseBranch?: string;
    /** PR title (default: task title). */
    title?: string;
    /** PR body text (default includes "Fixes #<issue>" and task description). */
    body?: string;
    /** Whether to create the PR as draft. */
    draft?: boolean;
  } & Record<string, JsonValue>;
  /** Get full GitHub integration details for a task board card, including remote issue title, body, labels, pull request details, and synchronization state. */
  task_board_github_get: {
    /** Task ID on the board. */
    taskId?: string;
    /** Repository owner (used with repository and issueNumber). */
    owner?: string;
    /** Repository name (used with owner and issueNumber). */
    repository?: string;
    /** GitHub issue number. */
    issueNumber?: number;
  } & Record<string, JsonValue>;
  /** Link an existing GitHub Pull Request to a task board card linked to a GitHub issue, updating PR metadata and managed phase labels. */
  task_board_github_link_pr: {
    /** Task ID linked to a GitHub issue. */
    taskId: string;
    /** Pull request number on GitHub. */
    pullRequestNumber: number;
  } & Record<string, JsonValue>;
  /** List task board cards associated with GitHub issues, with their remote issue state, remote labels, and pull request metadata. */
  task_board_github_list: {
    /** Filter by repository owner. */
    owner?: string;
    /** Filter by repository name. */
    repository?: string;
    /** Filter by remote issue state (open, closed, or all; default: all). */
    state?: "open" | "closed" | "all";
    /** Filter by whether a pull request is linked. */
    hasPr?: boolean;
  } & Record<string, JsonValue>;
  /** Trigger synchronization between GitHub issues/pull requests and the task board for a task, a repository, or all configured repositories. */
  task_board_github_refresh: {
    /** Specific task ID to refresh. */
    taskId?: string;
    /** Repository owner to refresh. */
    owner?: string;
    /** Repository name to refresh. */
    repository?: string;
  } & Record<string, JsonValue>;
  /** Read and edit the repositories the GitHub Issues integration synchronizes with the task board. An issue is included when it carries the inclusion label or is assigned to the configured assignee. A repository is written to the plugin configuration as soon as the call returns, so no restart is needed. */
  task_board_github_repositories: {
    /** list reads the configured repositories; add, remove and update rewrite the list. */
    action: "list" | "add" | "remove" | "update";
    /** Repository to act on: owner/repo, a GitHub URL, or an SSH remote. Required by add, remove and update. */
    repository?: string;
    /** Issue label that opts an issue into the board (default dsh). */
    inclusionLabel?: string;
    /** Login whose assigned issues are included too; use @me for the account the host is authenticated as, or an empty string to turn the channel off. Trivial filters such as "assigned to me" belong here. */
    assignee?: string;
    /** Whether issues assigned to nobody are included too; set it on repositories whose issues are never assigned. It never pulls in issues assigned to other people. */
    includeUnassigned?: boolean;
    /** Base branch pull requests target (default main). */
    baseBranch?: string;
    /** Whether the extension may open pull requests for completed cards. */
    prCreationEnabled?: boolean;
    /** Background polling interval in milliseconds (default 300000; 0 disables polling). */
    pollingIntervalMs?: number;
    /** Qualified provider/model the AI issue analysis uses for this repository's cards; an empty string falls back to the card's pinned model, then the host default. */
    analysisModel?: string;
  } & Record<string, JsonValue>;
  /** Configure the task board GitHub Issues integration: read the setup status, store or clear the GitHub token, and run a live connection test against GitHub. The token is stored host-side in the harness credential store and is never returned by any tool. Because a token passed as an argument becomes part of this conversation, prefer asking the user to paste it in the extension settings card when they can reach it. */
  task_board_github_setup: {
    /** status reads the current configuration; set-token stores the token; clear-token removes it; test calls GitHub. */
    action: "status" | "set-token" | "clear-token" | "test";
    /** GitHub token to store; required by set-token. It becomes part of this conversation. */
    token?: string;
    /** Repository owner to test only that repository. */
    owner?: string;
    /** Repository name to test only that repository. */
    repository?: string;
  } & Record<string, JsonValue>;
  /** List tasks on the DSH task board (the Host-authoritative ledger behind the Web GUI task board). Filters: status column, parentId (direct subtasks), rootsOnly, tag, free-text query, and archived inclusion. Returns each task id, title, column, parent/subtask link, execution targets, schedule and latest run outcome, plus the board summary (revision, time zone, subtask depth limit, session-default permission). Use task_board_get for one task in full, task_board_create to add work, and task_board_run to execute it. */
  task_board_list: {
    /** Only cards in this column. */
    status?: "backlog" | "todo" | "running" | "done" | "failed";
    /** Only the direct subtasks of this task id. */
    parentId?: string;
    /** Only tasks that have no parent (default false). */
    rootsOnly?: boolean;
    /** Include archived tasks (default false). */
    includeArchived?: boolean;
    /** Only tasks carrying this label name. */
    tag?: string;
    /** Case-insensitive match against title, description, prompt, and label names. */
    query?: string;
    /** Maximum rows to return (default 50, maximum 200). */
    limit?: number;
  } & Record<string, JsonValue>;
  /** Move, archive, restore, delete, or settle one task board card. move-backlog, move-todo, move-running, move-done and move-failed are the manual column moves and cover every column; a card the runner is executing (one with an open execution) cannot be moved. A manual move writes the card column only and never fabricates an execution record, so the card reports a declaration rather than evidence of a run: done/failed declare work finished (or failed) outside a Host-run execution — human work, an external system, a decision made elsewhere — and running says the work is under way without a tracked session. Use task_board_run when the work should actually run in a session here. settle force-closes the open execution of a card the board can no longer observe (a stuck running card) and records it cancelled with the caller as the reason, so the card returns to the todo column and can be run again. archive takes the whole subtask tree off the board and is refused while any member has an unsettled execution; restore brings the task, its ancestors and its subtree back; delete removes one card and is refused while it still has subtasks (detach or delete them first) or while it runs. It cannot confirm a permission binding: the confirmation gate is a human act performed in the board UI. */
  task_board_manage: {
    /** The task to act on. */
    taskId: string;
    /** The lifecycle operation to perform. */
    action: "move-todo" | "move-backlog" | "move-running" | "move-done" | "move-failed" | "archive" | "restore" | "delete" | "settle";
  } & Record<string, JsonValue>;
  /** Run a task on the board now, or re-run a settled one. Running a task also runs its whole subtask tree CONCURRENTLY: the Host opens one real DSH session per member under one run group, each replaying its card pinned workspace, agent preset, permission and model; a subtask that does not pin them inherits its nearest ancestor. The parent card stays in the running column until its own turn and every direct subtask have settled, and it fails when any member failed; one failing subtask never stops the others. A card whose effective permission is above the deployment session default is refused with confirmation-required until a HUMAN confirms the binding in the board UI; this tool cannot confirm it. A card whose task carries teamRun instead starts ONE Team Lead session and the Host spawns a teammate per subtask inside it, so those cards run as an Agent Team rather than as independent sessions; that mode needs the deployment Agent Teams service and is refused when it is missing. Executions consume real API quota. Sessions are created asynchronously, so read their ids and outcomes back with task_board_get. */
  task_board_run: {
    /** The task to run; running a root task runs its whole subtree. */
    taskId: string;
    /** Re-run a settled task: reset its column to todo before starting (default false). */
    rerun?: boolean;
  } & Record<string, JsonValue>;
  /** Arm, change, or disarm a task scheduled runs (5-field cron; day-of-month and day-of-week follow Vixie semantics: both restricted means OR, otherwise AND). The cron wall clock is read in the rule stored IANA time zone; omit timeZone to use the Host zone reported by task_board_list/task_board_get. DST gaps are skipped and an ambiguous fall-back time fires once, at the earlier instant. A due scheduled task runs the same cascade a manual run does, so a root task runs its whole subtask tree. A schedule whose tree contains an unconfirmed above-default permission is refused and rolls to its next occurrence; the reason is reported in the list board summary as schedulerError. Missed occurrences during Host downtime are skipped, never queued; a task that is already running skips its occurrence. */
  task_board_schedule: {
    /** The task whose schedule changes. */
    taskId: string;
    /** Arm (true) or disarm (false) the schedule. */
    enabled?: boolean;
    /** 5-field cron expression: minute hour day-of-month month day-of-week. */
    cron?: string;
    /** IANA zone the cron wall clock is read in (for example Asia/Shanghai). Omit to keep the stored zone, or pass an empty string to clear it back to the Host zone. */
    timeZone?: string;
  } & Record<string, JsonValue>;
  /** Attach an existing task under a parent (making it a subtask) or detach it back to the root board by setting its parentId. Pass an empty parentId to detach. The Host refuses the link when the parent is unknown or archived, when the moved task is one of its own descendants, when the resulting depth exceeds the deployment subtask limit (default one level, maximum three), or while the task has an unsettled execution (its link may still be a running cascade parent pointer). Running a task runs its whole subtree concurrently; a parent card settles only after its own turn and every direct subtask settle. */
  task_board_set_parent: {
    /** The task whose parent link changes. */
    taskId: string;
    /** Parent task id, or an empty string to detach the task back to the root board. */
    parentId: string;
  } & Record<string, JsonValue>;
  /** Edit a task board card: title, description, prompt, labels, and the execution targets (workspace, agent preset, permission, model, session reuse). Only the fields you pass change; pass an empty string to clear a target, or an empty labels array to clear the labels. Title, description and prompt freeze once the task has started executing; the execution targets stay editable because they only affect future runs. Changing the pinned permission re-arms the permission confirmation gate. */
  task_board_update: {
    /** Task id to edit. */
    taskId: string;
    /** New title (a blank title is refused by the Host). */
    title?: string;
    /** New description. */
    description?: string;
    /** New execution prompt. */
    prompt?: string;
    /** New workspace id; an empty string clears it. */
    workspaceId?: string;
    /** New agent preset id; an empty string clears it. */
    mode?: string;
    /** New permission preset; an empty string clears it back to the session default. */
    permission?: "read-only" | "workspace-write" | "danger-full-access" | "";
    /** New pinned model; an empty string clears it. */
    model?: string;
    /** Continue later runs in the previous execution session. */
    reuseSession?: boolean;
    /** Switches this task between a plain cascade (one session per member) and an Agent Team run (Lead session plus a teammate per subtask). */
    teamRun?: boolean;
    /** Whether each run starts with dsh built-in /goal (default true). Pass false to run one plain turn instead. */
    goalRun?: boolean;
    /** Whether this task runs without the board acceptance gate (default false, inherit the board-wide switch). Pass true to opt out; pass false to opt back in. Only affects executions started afterwards. */
    skipVerification?: boolean;
    /** Replacement label set; an empty array clears all labels. */
    tags?: {
      /** Label name. */
      name: string;
      /** Optional prompt line injected before the task prompt. */
      promptPrefix?: string;
    }[];
  } & Record<string, JsonValue>;
  /** Record and update a task list to plan multi-step work and show progress; skip it for trivial single-step tasks. Add one todo per concrete step before you start. While work remains, keep the todos being worked on `in_progress`, several only when work runs in parallel. Mark each todo `completed` as soon as it is done. */
  todo_write: {
    /** The COMPLETE task list, replacing any previous list. */
    todos: ({
      /** What the task is — a short imperative line. */
      content: string;
      /** pending (not started) | in_progress (now) | completed (done). */
      status: "pending" | "in_progress" | "completed";
    })[];
  } & Record<string, JsonValue>;
  /** Update the current goal. */
  update_goal: {
    /** Exact id returned by get_goal. */
    goal_id: string;
    /** Exact positive revision returned by get_goal. */
    revision: number;
    /** edit, pause, and resume require a direct top-level human request. complete and blocked are also allowed during an automatic continuation of this goal; blocked is rejected before the configured minimum round count. */
    action: "edit" | "pause" | "resume" | "complete" | "blocked";
    /** Replacement objective; valid only with action edit. */
    objective?: string;
    /** Replacement cap; valid only with action edit. */
    max_goal_rounds?: number;
    /** Required only with action blocked: the concrete condition that persisted across rounds and blocks progress. */
    blocked_reason?: string;
  } & Record<string, JsonValue>;
  /** View the current selection on the image-gen workbench infinite canvas as an image (a screenshot the canvas pushed for its selection: hand-drawn sketches, annotated images, or any selected shapes). Call it after canvas_state confirms a selection exists. When nothing is selected, ask the user to select the shapes first. The image becomes part of the conversation, so you can reason about it directly. */
  view_canvas: Record<string, JsonValue>;
  /** Fetch the content of a specific HTTP(S) URL and return it decoded to text. */
  web_fetch: {
    /** The HTTP(S) URL to fetch. */
    url: string;
  } & Record<string, JsonValue>;
  /** Run a JavaScript workflow script that orchestrates subagents at scale. Use this for work that fans out across many independent pieces — an audit over many files, a migration, multi-angle research, adversarial verification of findings — where you write the orchestration as a script instead of delegating turn by turn. Script-body hooks: - `agent(prompt, opts?): Promise<any>` — run one subagent to completion. Without `opts.schema` it resolves to the child's final text; with `opts.schema` (an object-rooted JSON Schema using ONLY type/properties/required/additionalProperties/items/enum/const/oneOf) it resolves to the validated object. Resolves `null` when the child fails (filter with `.filter(Boolean)`). Other opts: `label` (display), `phase` (progress group), and independent `provider`/`model` LLM target overrides. - `pipeline(items, ...stages): Promise<any[]>` — run each item through the stages independently with NO barrier between stages (prefer this for multi-stage work). Each stage receives `(prev, item, index)`. A stage throw drops that ITEM to `null` and skips its remaining stages. - `parallel(thunks): Promise<any[]>` — run zero-argument functions concurrently and await ALL of them (a barrier; use only when a stage genuinely needs every prior result together). A throwing thunk resolves to `null`. - `phase(title)` — start a progress phase; `log(message)` — narrate progress; `args` — the tool call's `args` input, verbatim. Misused hooks (bad arguments, unknown options, unsupported schemas, tripped caps) end the whole script instead of producing `null`. The script has no filesystem, network, timer, or Node.js APIs; the agents do the work. */
  workflow: {
    /** The plain JavaScript body, not TypeScript and without an `export const meta` statement; top-level await is allowed. End with `return <value>`; the JSON-serializable value is this tool's result. */
    script: string;
    /** The workflow identity as plain JSON, not code. */
    meta: {
      /** Short kebab-case workflow name. */
      name: string;
      /** One-line description of what the workflow does. */
      description: string;
      /** Optional guidance on when this workflow applies. */
      whenToUse?: string;
      /** Optional phase declarations matched by phase() calls. */
      phases?: ({
        /** The phase title phase() calls match by exact string. */
        title: string;
        /** Optional one-line description of the phase. */
        detail?: string;
        /** Optional provider override this phase is expected to use. */
        provider?: string;
        /** Optional model override this phase is expected to use. */
        model?: string;
      } & Record<string, JsonValue>)[];
    } & Record<string, JsonValue>;
    /** Optional JSON input exposed to the script as the `args` global (wrap a bare list as a field, e.g. {"files": [...]}). */
    args?: Record<string, JsonValue>;
    /** Run as a background job: return a job id immediately instead of waiting; the return value arrives with the completion notice. */
    run_in_background?: boolean;
  } & Record<string, JsonValue>;
  /** Create or fully replace a UTF-8 text file. */
  write: {
    /** Path to write, resolved by the filesystem backend. */
    file_path: string;
    /** Full UTF-8 text content to write. */
    content: string;
    /** The narrowest wider sandbox mode for a one-shot retry of the exact operation the sandbox just denied; the retry asks the user for approval. */
    sandbox_permissions?: "workspace-write" | "danger-full-access";
    /** Required with sandbox_permissions: one sentence for the user explaining why this exact file operation needs the wider access. Use the language of the user’s current request. */
    justification?: string;
  } & Record<string, JsonValue>;
}

